func newDoctorRewriteCheckpointsCmd() *cobra.Command {
	var dryRun bool
	var force bool
	var remote string

	cmd := &cobra.Command{
		Use:   "rewrite-checkpoints",
		Short: "Re-materialize git-branch checkpoints as per-checkpoint git refs (fresh commits)",
		Long: `Rewrite the checkpoints stored on the entire/checkpoints/v1 branch into
per-checkpoint refs under refs/entire/checkpoints/<shard>/<id>, the layout the
git-refs checkpoint store uses.

Unlike a byte-identical copy, each checkpoint is written fresh through the
git-refs store: the transcript is replayed (regenerating the compact
transcript.jsonl), everything is rooted at the checkpoint (no shard folders),
and per-session summaries and combined attribution are replayed. The checkpoint
id is preserved and each commit keeps the original author. Any subagent tasks/
subtree is grafted in unchanged.

Idempotent: checkpoints that already have a ref are skipped (use --force to
re-materialize them from scratch).

New refs are queued for push. Run interactively, it asks whether to push them
now; non-interactively it never pushes — the refs stay queued and flush on the
next push once the git-refs store is the configured primary.`,
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()
			out := cmd.OutOrStdout()

			repo, err := strategy.OpenRepository(ctx)
			if err != nil {
				return fmt.Errorf("open repository: %w", err)
			}
			defer repo.Close()

			result, err := checkpoint.RewriteBranchToRefs(ctx, repo, dryRun, force)
			if err != nil {
				if errors.Is(err, context.Canceled) {
					return NewSilentError(err)
				}
				return fmt.Errorf("rewrite checkpoints: %w", err)
			}

			if result.Total == 0 {
				fmt.Fprintln(out, "No checkpoints found on the v1 branch — nothing to rewrite.")
				return nil
			}

			verb := "Rewrote"
			if dryRun {
				verb = "Would rewrite"
			}
			fmt.Fprintf(out, "%s %d checkpoint(s) to refs (%d already present, %d total).\n",
				verb, len(result.Rewritten), result.Skipped, result.Total)

			if dryRun || len(result.Rewritten) == 0 {
				return nil
			}

			if !interactive.CanPromptInteractively() {
				fmt.Fprintln(out, "Refs are queued; they push on the next `git push` once git-refs is the primary store.")
				return nil
			}

			title := fmt.Sprintf("Push %d rewritten checkpoint ref(s) now?", len(result.Rewritten))
			confirmed, err := confirmDoctorFix(ctx, out, title)
			if err != nil {
				return err
			}
			if !confirmed {
				fmt.Fprintln(out, "Refs stay queued for the next push.")
				return nil
			}

			pushed, err := strategy.PushMigratedCheckpointRefs(ctx, repo, remote)
			if err != nil {
				if errors.Is(err, context.Canceled) {
					return NewSilentError(err)
				}
				return fmt.Errorf("push rewritten refs: %w", err)
			}
			if pushed == 0 {
				fmt.Fprintln(out, "Checkpoint pushing is disabled in settings; refs stay queued for the next push.")
				return nil
			}
			fmt.Fprintf(out, "Pushed %d checkpoint ref(s).\n", pushed)
			return nil
		},
	}
	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "Report what would be rewritten without writing refs")
	cmd.Flags().BoolVar(&force, "force", false, "Re-materialize checkpoints whose ref already exists")
	cmd.Flags().StringVar(&remote, "remote", "origin", "Remote to push rewritten refs to when confirmed")
	return cmd
}

