26	// gitRefsStore is the git-backed persistent checkpoint store that keeps one ref
27	// per checkpoint at refs/entire/checkpoints/<shard>/<id>. Each ref points at a
28	// commit whose tree root IS that checkpoint's contents (metadata.json, 0/, 1/,
29	// tasks/…), so updates advance the ref and preserve per-checkpoint history. It
30	// shares the checkpoint-subtree machinery with the git-branch store via the
31	// embedded *treeWriter (anchored at basePath ""), differing only in where the
32	// subtree is committed: a per-checkpoint ref instead of the v1 branch.
33	type gitRefsStore struct {
34		*treeWriter
35	
36		blobFetcher BlobFetchFunc
37		refFetcher  RefFetchFunc
38	}
39	
40	// newGitRefsStore constructs the per-checkpoint-ref store for a repository.
41	func newGitRefsStore(repo *git.Repository) *gitRefsStore {
42		return &gitRefsStore{treeWriter: &treeWriter{repo: repo}}
43	}
