56	// Write dispatches a persistent write request to the matching ref operation,
57	// mirroring the git-branch store's Write.
58	func (s *gitRefsStore) Write(ctx context.Context, req WriteRequest) error {
59		switch r := req.(type) {
60		case Session:
61			return s.writeSession(ctx, WriteOptions(r))
62		case SessionTranscript:
63			return s.backfillTranscript(ctx, UpdateOptions(r))
64		case SessionSummary:
65			return s.backfillSummary(ctx, r.CheckpointID, r.Summary)
66		case CheckpointAttribution:
67			return s.backfillAttribution(ctx, r.CheckpointID, r.Attribution)
68		default:
69			return fmt.Errorf("checkpoint: unsupported write request %T", req)
70		}
71	}
