73	// refBase resolves a checkpoint ref's current tip commit (the parent for the
74	// next write) and subtree object (the checkpoint's current contents). A missing
75	// ref yields (ZeroHash, nil) so the next write becomes an orphan commit.
76	func (s *gitRefsStore) refBase(cid id.CheckpointID) (plumbing.Hash, *object.Tree, error) {
77		refName, err := RefName(cid)
78		if err != nil {
79			return plumbing.ZeroHash, nil, err
80		}
81		ref, err := s.repo.Reference(refName, true)
82		if errors.Is(err, plumbing.ErrReferenceNotFound) {
83			return plumbing.ZeroHash, nil, nil // no ref yet → new checkpoint (orphan)
84		}
85		if err != nil {
86			// A real lookup failure (IO/corruption), not an absent ref: surface it
87			// rather than silently starting a fresh orphan history over the ref.
88			return plumbing.ZeroHash, nil, fmt.Errorf("resolve checkpoint ref %s: %w", refName, err)
89		}
90		commit, err := s.repo.CommitObject(ref.Hash())
91		if err != nil {
92			return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint commit %s: %w", ref.Hash(), err)
93		}
94		tree, err := commit.Tree()
95		if err != nil {
96			return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint tree for %s: %w", cid, err)
97		}
98		return ref.Hash(), tree, nil
99	}
