101	// setRef points a checkpoint's ref at a new commit and records it for push.
102	// Enqueue is best-effort: a write that lands locally but fails to enqueue must
103	// not fail condensation. The ref is still local; only its remote sync is missed
104	// until a later write to the same checkpoint re-enqueues it.
105	func (s *gitRefsStore) setRef(ctx context.Context, cid id.CheckpointID, hash plumbing.Hash) error {
106		refName, err := RefName(cid)
107		if err != nil {
108			return err
109		}
110		if err := s.repo.Storer.SetReference(plumbing.NewHashReference(refName, hash)); err != nil {
111			return fmt.Errorf("set checkpoint ref %s to %s: %w", refName, hash, err)
112		}
113		s.enqueueForPush(ctx, refName)
114		return nil
115	}
