117	// enqueueForPush records refName in the push-discovery queue, logging (never
118	// returning) on failure so the local ref write still succeeds.
119	func (s *gitRefsStore) enqueueForPush(ctx context.Context, refName plumbing.ReferenceName) {
120		q, err := PushQueueForRepo(ctx, s.repo)
121		if err != nil {
122			logging.Warn(ctx, "checkpoint: resolve push queue failed; ref not enqueued",
123				slog.String("ref", refName.String()), slog.String("error", err.Error()))
124			return
125		}
126		if err := q.Enqueue(refName); err != nil {
127			logging.Warn(ctx, "checkpoint: enqueue checkpoint ref for push failed",
128				slog.String("ref", refName.String()), slog.String("error", err.Error()))
129		}
130	}
