132	func (s *gitRefsStore) writeSession(ctx context.Context, opts WriteOptions) error {
133		if opts.CheckpointID.IsEmpty() {
134			return errors.New("invalid checkpoint options: checkpoint ID is required")
135		}
136		if err := validation.ValidateSessionID(opts.SessionID); err != nil {
137			return fmt.Errorf("invalid checkpoint options: %w", err)
138		}
139		if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
140			return fmt.Errorf("invalid checkpoint options: %w", err)
141		}
142		if err := validation.ValidateAgentID(opts.AgentID); err != nil {
143			return fmt.Errorf("invalid checkpoint options: %w", err)
144		}
145	
146		parentHash, existing, err := s.refBase(opts.CheckpointID)
147		if err != nil {
148			return err
149		}
150	
151		checkpointSubtree, taskMetadataPath, err := s.applySessionWrite(ctx, opts, existing, "")
152		if err != nil {
153			return err
154		}
155	
156		commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
157		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
158		if err != nil {
159			return err
160		}
161		return s.setRef(ctx, opts.CheckpointID, commitHash)
162	}
