239	// checkpointTree resolves a FetchingTree rooted at a checkpoint's ref commit
240	// tree (which is the checkpoint subtree itself). Returns ErrCheckpointNotFound
241	// when the ref or its commit/tree cannot be resolved.
242	func (s *gitRefsStore) checkpointTree(ctx context.Context, cid id.CheckpointID) (*FetchingTree, error) {
243		if err := ctx.Err(); err != nil {
244			return nil, err //nolint:wrapcheck // Propagating context cancellation
245		}
246		ref, err := s.resolveRefMaybeFetch(ctx, cid)
247		if err != nil {
248			if errors.Is(err, plumbing.ErrReferenceNotFound) {
249				return nil, ErrCheckpointNotFound
250			}
251			return nil, err
252		}
253		commit, err := s.repo.CommitObject(ref.Hash())
254		if err != nil {
255			// The ref resolved but its commit object doesn't — corruption/IO, not an
256			// absent checkpoint. Surface it instead of masking as "not found".
257			return nil, fmt.Errorf("read checkpoint commit %s for %s: %w", ref.Hash(), cid, err)
258		}
259		tree, err := commit.Tree()
260		if err != nil {
261			return nil, fmt.Errorf("read checkpoint tree for %s: %w", cid, err)
262		}
263		return NewFetchingTree(ctx, tree, s.repo.Storer, s.blobFetcher), nil
264	}
