266	// resolveRefMaybeFetch resolves a checkpoint ref, fetching it from the remote
267	// once when it is missing locally and a ref fetcher is configured (the
268	// checkpoint may have been written on another machine). It distinguishes a
269	// genuinely absent ref (returns a plumbing.ErrReferenceNotFound-wrapped error,
270	// which callers map to ErrCheckpointNotFound) from a real failure — an IO error,
271	// or a fetch that failed for network/context reasons — which is returned as-is
272	// so it is not silently swallowed as "checkpoint not found".
273	func (s *gitRefsStore) resolveRefMaybeFetch(ctx context.Context, cid id.CheckpointID) (*plumbing.Reference, error) {
274		refName, err := RefName(cid)
275		if err != nil {
276			return nil, err
277		}
278		ref, err := s.repo.Reference(refName, true)
279		if err == nil {
280			return ref, nil
281		}
282		if !errors.Is(err, plumbing.ErrReferenceNotFound) {
283			return nil, fmt.Errorf("resolve checkpoint ref %s: %w", refName, err)
284		}
285		if s.refFetcher == nil {
286			return nil, err //nolint:wrapcheck // genuinely absent; caller maps ErrReferenceNotFound to ErrCheckpointNotFound
287		}
288		if fetchErr := s.refFetcher(ctx, refName); fetchErr != nil {
289			logging.Debug(ctx, "git-refs: on-demand checkpoint ref fetch failed",
290				slog.String("ref", refName.String()), slog.String("error", fetchErr.Error()))
291			return nil, fmt.Errorf("fetch checkpoint ref %s: %w", refName, fetchErr)
292		}
293		// Re-resolve after a successful fetch. ErrReferenceNotFound here means the
294		// remote genuinely has no such checkpoint; anything else is a real error.
295		ref, err = s.repo.Reference(refName, true)
296		if err != nil {
297			return nil, err //nolint:wrapcheck // ErrReferenceNotFound (absent) or a real error; caller distinguishes via errors.Is
298		}
299		return ref, nil
300	}
