360	// List enumerates local checkpoint refs and reads each root summary, sorted most
361	// recent first. Storage-level listing is local-refs-only for now (no remote
362	// enumeration), matching the issue's first-version scope.
363	func (s *gitRefsStore) List(ctx context.Context) ([]CheckpointInfo, error) {
364		if err := ctx.Err(); err != nil {
365			return nil, err //nolint:wrapcheck // Propagating context cancellation
366		}
367	
368		refs, err := s.repo.References()
369		if err != nil {
370			return nil, fmt.Errorf("list checkpoint refs: %w", err)
371		}
372		defer refs.Close()
373	
374		var checkpoints []CheckpointInfo
375		err = refs.ForEach(func(ref *plumbing.Reference) error {
376			cid, ok := ParseRef(ref.Name())
377			if !ok {
378				return nil
379			}
380			commit, commitErr := s.repo.CommitObject(ref.Hash())
381			if commitErr != nil {
382				return nil //nolint:nilerr // skip unreadable refs, keep listing
383			}
384			tree, treeErr := commit.Tree()
385			if treeErr != nil {
386				return nil //nolint:nilerr // skip unreadable refs, keep listing
387			}
388			checkpoints = append(checkpoints, readCommittedInfoFromCheckpointTree(cid, tree))
389			return nil
390		})
391		if err != nil {
392			return nil, fmt.Errorf("iterate checkpoint refs: %w", err)
393		}
394	
395		sort.Slice(checkpoints, func(i, j int) bool {
396			return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
397		})
398		return checkpoints, nil
399	}
